new = '''def build_types(definitions) -> dict:
    """Resolve the declared type list into a name -> Type table."""
    if not isinstance(definitions, list):
        raise InvalidCampaign("types must be a list")
    table = {}
    pending = []
    for definition in definitions:
        _need(isinstance(definition, dict), "type definition must be an object")
        name = _identifier(definition.get("name"))
        kind = definition.get("kind")
        _need(isinstance(kind, str), "type kind must be a string")
        _need(name not in table, "duplicate type name")
        if kind == "bool":
            type = Bool()
        elif kind == "char":
            type = Char()
        elif kind == "int":
            bits = _integer(definition.get("bits"))
            _need(1 <= bits <= 64, "int bits out of range")
            type = Int(bits)
        elif kind == "string":
            maxsize = _integer(definition.get("maxsize"))
            _need(0 <= maxsize <= 512, "string maxsize out of range")
            type = String(maxsize)
        elif kind == "enum":
            values = definition.get("values")
            _need(isinstance(values, list) and values, "enum values expected")
            for value in values:
                _need(isinstance(value, str) and value and value.isascii()
                      and value.isprintable() and len(value) <= 64,
                      "enum value must be printable ASCII")
            _need(len(set(values)) == len(values), "duplicate enum value")
            type = Enum(name, values)
        elif kind == "array":
            size = _integer(definition.get("size"))
            _need(0 <= size <= 4096, "array size out of range")
            type = Array(None, size)
            pending.append((type, "element", definition.get("element")))
        elif kind == "struct":
            type = Struct(name)
            fields = definition.get("fields")
            _need(isinstance(fields, list), "struct fields must be a list")
            _need(len(fields) <= 16, "too many struct fields")
            pairs = []
            for entry in fields:
                _need(isinstance(entry, list) and len(entry) == 2,
                      "struct field pair expected")
                field = _identifier(entry[0])
                target = entry[1]
                _need(isinstance(target, str), "field type name expected")
                _need(all(field != other for other, _ in pairs),
                      "duplicate struct field")
                pairs.append((field, target))
            pending.append((type, "fields", pairs))
        elif kind == "alias":
            type = Alias(name, None)
            pending.append((type, "target", definition.get("target")))
        elif kind == "void":
            type = Void()
        else:
            raise InvalidCampaign("unknown type kind")
        type.decl = name
        table[name] = type
    # Second pass links forward references; aggregates never contain void.
    for type, role, payload in pending:
        if role == "fields":
            resolved = {}
            for field, target in payload:
                _need(target in table, "unknown struct field type")
                child = table[target]
                _need(not isinstance(underlying(child), Void),
                      "aggregate contains void")
                resolved[field] = child
            type.fields = resolved
        else:
            _need(isinstance(payload, str), "type reference expected")
            _need(payload in table, "unknown type reference")
            child = table[payload]
            if role == "element":
                _need(not isinstance(underlying(child), Void),
                      "aggregate contains void")
                type.element_type = child
            else:
                _need(not isinstance(child, Void), "alias to void")
                type.type = child
    _check_acyclic(table)
    _check_depth(table)
    return table


def _children(type):
    if isinstance(type, Alias):
        return (type.type,)
    if isinstance(type, Array):
        return (type.element_type,)
    if isinstance(type, Struct):
        return tuple(type.fields.values())
    return ()


def _check_acyclic(table):
    colour = {}
    for root in table:
        if colour.get(root):
            continue
        stack = [(root, iter(_children(table[root])))]
        colour[root] = 1
        while stack:
            node, walker = stack[-1]
            for child in walker:
                name = child.decl
                if colour.get(name) == 1:
                    raise InvalidCampaign("cyclic type graph")
                if colour.get(name) == 2:
                    continue
                colour[name] = 1
                stack.append((name, iter(_children(table[name]))))
                break
            else:
                colour[node] = 2
                stack.pop()


def _check_depth(table):
    depth = {}
    for root in table:
        if root in depth:
            continue
        stack = [(root, 0)]
        while stack:
            node, level = stack.pop()
            current = depth.get(node)
            if current is not None and current >= level:
                continue
            depth[node] = level
            for child in _children(table[node]):
                stack.append((child.decl, level + 1))
    for name, level in depth.items():
        _need(level <= MAX_DEPTH, "type nesting too deep")


'''
